public static List<string> CheckCircuits(Document doc)
{
    var circuits = new FilteredElementCollector(doc)
        .OfClass(typeof(ElectricalSystem)).ToElements();
    var results = new List<string>();
    foreach (var elem in circuits)
    {
        var circuit = elem as ElectricalSystem;
        if (circuit == null || circuit.SystemType != ElectricalSystemType.PowerCircuit) continue;
        double load = circuit.ApparentLoad / circuit.Voltage;
        var rating = circuit.LookupParameter("Rating");
        if (rating == null) continue;
        double breaker = rating.AsDouble();
        bool ok = load <= breaker * 0.80;
        results.Add($"Circuit {circuit.CircuitNumber}: {load:F1}A/{breaker}A - {(ok ? "PASS" : "FAIL")}");
    }
    return results;
}

