public static List<string> CheckRoofEquipmentClearance(Document doc)
{
    List<string> results = new List<string>();
    double minElevation = 6.0 / 12.0; // 6 inches in feet
    double minEdgeDist = 10.0; // feet

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> equipment = collector
        .OfCategory(BuiltInCategory.OST_MechanicalEquipment)
        .WhereElementIsNotElementType()
        .ToElements();

    // Get roof elements for edge distance
    FilteredElementCollector roofCollector = new FilteredElementCollector(doc);
    IList<Element> roofs = roofCollector
        .OfCategory(BuiltInCategory.OST_Roofs)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element equip in equipment)
    {
        FamilyInstance fi = equip as FamilyInstance;
        if (fi == null) continue;

        // Check if on roof level
        Parameter levelParam = fi.get_Parameter(BuiltInParameter.FAMILY_LEVEL_PARAM);
        if (levelParam == null) continue;
        Level level = doc.GetElement(levelParam.AsElementId()) as Level;
        if (level == null || !level.Name.ToLower().Contains("roof")) continue;

        // Check elevation above roof
        Parameter offsetParam = fi.get_Parameter(BuiltInParameter.INSTANCE_FREE_HOST_OFFSET_PARAM);
        double offset = offsetParam != null ? offsetParam.AsDouble() : 0;
        bool elevOk = offset >= minElevation;

        // Check distance from roof edge
        LocationPoint loc = fi.Location as LocationPoint;
        bool edgeOk = true; // Default pass, detailed geometry check below
        if (loc != null)
        {
            foreach (Element roofElem in roofs)
            {
                BoundingBoxXYZ roofBb = roofElem.get_BoundingBox(null);
                if (roofBb == null) continue;
                double distToEdge = Math.Min(
                    Math.Min(loc.Point.X - roofBb.Min.X, roofBb.Max.X - loc.Point.X),
                    Math.Min(loc.Point.Y - roofBb.Min.Y, roofBb.Max.Y - loc.Point.Y));
                if (distToEdge < minEdgeDist) edgeOk = false;
            }
        }

        bool compliant = elevOk && edgeOk;
        results.Add($"Equipment {fi.Id} ({fi.Symbol.FamilyName}): Elevation={offset * 12:F1}in, EdgeOk={edgeOk} - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

rule ibc_occupant_load:
    where:
        element.type == "space"
        element.requires_occupant_load == True
    must:
        # Occupant load = floor area / occupant load factor
        if space.use == "assembly_standing":
            space.occupant_load >= space.floor_area / 5.sqft_per_person
        elif space.use == "assembly_concentrated":
            space.occupant_load >= space.floor_area / 7.sqft_per_person
        elif space.use == "assembly_unconcentrated":
            space.occupant_load >= space.floor_area / 15.sqft_per_person
        elif space.use == "business":
            space.occupant_load >= space.floor_area / 150.sqft_per_person
        elif space.use == "educational_classroom":
            space.occupant_load >= space.floor_area / 20.sqft_per_person
        elif space.use == "mercantile_sales":
            space.occupant_load >= space.floor_area / 60.sqft_per_person
        elif space.use == "industrial":
            space.occupant_load >= space.floor_area / 100.sqft_per_person
