public static List<string> CheckDuctVelocity(Document doc)
{
    List<string> results = new List<string>();
    double maxVelocityFpm = 2000.0;

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> ducts = collector
        .OfCategory(BuiltInCategory.OST_DuctCurves)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in ducts)
    {
        Duct duct = elem as Duct;
        if (duct == null) continue;

        // Check system type
        Parameter sysParam = duct.get_Parameter(BuiltInParameter.RBS_DUCT_SYSTEM_TYPE_PARAM);
        if (sysParam == null) continue;
        string sysType = sysParam.AsValueString();
        if (!sysType.ToLower().Contains("supply")) continue;

        // Get velocity
        Parameter velParam = duct.get_Parameter(BuiltInParameter.RBS_VELOCITY);
        if (velParam == null) continue;
        double velocity = velParam.AsDouble(); // ft/s in internal units
        double velocityFpm = velocity * 60.0; // Convert to ft/min

        // Get flow
        Parameter flowParam = duct.get_Parameter(BuiltInParameter.RBS_DUCT_FLOW_PARAM);
        double flow = flowParam != null ? flowParam.AsDouble() : 0;

        bool compliant = velocityFpm <= maxVelocityFpm;
        results.Add($"Duct {duct.Id}: Velocity={velocityFpm:F0}FPM, Flow={flow:F0}CFM - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

