public static List<string> CheckTrapSizes(Document doc)
{
    List<string> results = new List<string>();
    double minTrapDiameterFeet = 1.5 / 12.0;

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> fixtures = collector
        .OfCategory(BuiltInCategory.OST_PlumbingFixtures)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element fixture in fixtures)
    {
        FamilyInstance fi = fixture as FamilyInstance;
        if (fi == null) continue;

        // Check if fixture is a bathtub by family name
        string familyName = fi.Symbol.FamilyName.ToLower();
        if (!familyName.Contains("bathtub") && !familyName.Contains("bath_tub") && !familyName.Contains("tub")) continue;

        // Look for trap diameter parameter
        Parameter trapParam = fi.LookupParameter("Trap Diameter");
        if (trapParam == null)
            trapParam = fi.LookupParameter("Trap Size");

        if (trapParam != null)
        {
            double trapDia = trapParam.AsDouble(); // feet
            double trapDiaInches = trapDia * 12.0;
            bool compliant = trapDia >= minTrapDiameterFeet;
            results.Add($"Fixture {fi.Id} ({fi.Symbol.FamilyName}): Trap={trapDiaInches:F2}in - {(compliant ? "PASS" : "FAIL")}");
        }
        else
        {
            results.Add($"Fixture {fi.Id} ({fi.Symbol.FamilyName}): No trap parameter - NEEDS REVIEW");
        }
    }

    return results;
}

