public static List<string> CheckRampSlope(Document doc)
{
    List<string> results = new List<string>();
    double maxSlope = 1.0 / 20.0; // 5% grade = 1:20

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> ramps = collector
        .OfCategory(BuiltInCategory.OST_Ramps)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in ramps)
    {
        Parameter slopeParam = elem.get_Parameter(BuiltInParameter.RAMP_ATTR_MAX_SLOPE);
        if (slopeParam == null)
            slopeParam = elem.LookupParameter("Slope");

        if (slopeParam != null)
        {
            double slope = slopeParam.AsDouble(); // slope as rise/run ratio
            bool compliant = slope <= maxSlope;
            double slopePercent = slope * 100.0;
            results.Add($"Ramp {elem.Id}: Slope={slopePercent:F1}% (1:{1.0/slope:F0}) - {(compliant ? "PASS" : "FAIL")}");
        }
        else
        {
            // Calculate from geometry
            BoundingBoxXYZ bb = elem.get_BoundingBox(null);
            if (bb != null)
            {
                double rise = bb.Max.Z - bb.Min.Z;
                double run = Math.Sqrt(
                    Math.Pow(bb.Max.X - bb.Min.X, 2) +
                    Math.Pow(bb.Max.Y - bb.Min.Y, 2));
                double calcSlope = run > 0 ? rise / run : 0;
                bool compliant = calcSlope <= maxSlope;
                results.Add($"Ramp {elem.Id}: Slope~{calcSlope * 100:F1}% - {(compliant ? "PASS" : "FAIL")}");
            }
        }
    }

    return results;
}

public static List<string> CheckColumnMinDimension(Document doc)
{
    List<string> results = new List<string>();
    double minDimFeet = UnitUtils.ConvertToInternalUnits(200, UnitTypeId.Millimeters);

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> columns = collector
        .OfCategory(BuiltInCategory.OST_StructuralColumns)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in columns)
    {
        FamilyInstance col = elem as FamilyInstance;
        if (col == null) continue;

        // Check if concrete
        Parameter matParam = col.get_Parameter(BuiltInParameter.STRUCTURAL_MATERIAL_PARAM);
        if (matParam != null)
        {
            Material mat = doc.GetElement(matParam.AsElementId()) as Material;
            if (mat != null && !mat.Name.ToLower().Contains("concrete")) continue;
        }

        // Get column width and depth parameters
        Parameter widthParam = col.Symbol.LookupParameter("b");
        Parameter depthParam = col.Symbol.LookupParameter("h");
        if (widthParam == null) widthParam = col.Symbol.LookupParameter("Width");
        if (depthParam == null) depthParam = col.Symbol.LookupParameter("Depth");

        double minDim = double.MaxValue;
        if (widthParam != null) minDim = Math.Min(minDim, widthParam.AsDouble());
        if (depthParam != null) minDim = Math.Min(minDim, depthParam.AsDouble());

        if (minDim < double.MaxValue)
        {
            bool compliant = minDim >= minDimFeet;
            double dimMm = UnitUtils.ConvertFromInternalUnits(minDim, UnitTypeId.Millimeters);
            results.Add($"Column {col.Id} ({col.Symbol.Name}): MinDim={dimMm:F0}mm - {(compliant ? "PASS" : "FAIL")}");
        }
    }

    return results;
}

