public static List<string> CheckCircuitLoading(Document doc)
{
    List<string> results = new List<string>();

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> circuits = collector
        .OfClass(typeof(ElectricalSystem))
        .ToElements();

    foreach (Element elem in circuits)
    {
        ElectricalSystem circuit = elem as ElectricalSystem;
        if (circuit == null) continue;
        if (circuit.SystemType != ElectricalSystemType.PowerCircuit) continue;

        double apparentLoad = circuit.ApparentLoad; // VA
        double voltage = circuit.Voltage;
        if (voltage == 0) continue;
        double currentLoad = apparentLoad / voltage; // Amps

        Parameter ratingParam = circuit.LookupParameter("Rating");
        double breakerRating = ratingParam != null ? ratingParam.AsDouble() : 0;
        if (breakerRating == 0)
        {
            results.Add($"Circuit {circuit.Id} ({circuit.CircuitNumber}): No breaker rating - NEEDS REVIEW");
            continue;
        }

        double maxAllowedLoad = breakerRating * 0.80;
        bool compliant = currentLoad <= maxAllowedLoad;

        results.Add($"Circuit {circuit.Id} ({circuit.CircuitNumber}): Load={currentLoad:F1}A, Breaker={breakerRating}A, Max80%={maxAllowedLoad:F1}A - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

constraint flat_roof_snow_load:
    where:
        element.type == "roof"
        element.slope <= 5.degrees
    require:
        # Flat roof snow load: pf = 0.7 * Ce * Ct * Is * pg
        let pg = structural.ground_snow_load(element.building.location)
        let Ce = structural.exposure_factor(element.building.exposure_category, element.building.terrain_category)
        let Ct = structural.thermal_factor(element.building.thermal_condition)
        let Is = structural.importance_factor_snow(element.building.risk_category)
        let pf = 0.7 * Ce * Ct * Is * pg
        # Minimum snow load for low-slope roofs
        let pf_min = Is * pg * structural.min_snow_factor(pg)
        element.design_snow_load >= max(pf, pf_min)
