public static List<string> CheckElevatorSigns(Document doc)
{
    List<string> results = new List<string>();

    // Find all elevator elements
    FilteredElementCollector elevCollector = new FilteredElementCollector(doc);
    IList<Element> elevators = elevCollector
        .OfCategory(BuiltInCategory.OST_GenericModel)
        .WhereElementIsNotElementType()
        .ToElements()
        .Where(e => {
            FamilyInstance fi = e as FamilyInstance;
            return fi != null && fi.Symbol.FamilyName.ToLower().Contains("elevator");
        }).ToList();

    // Find all sign/annotation elements
    FilteredElementCollector signCollector = new FilteredElementCollector(doc);
    IList<Element> signs = signCollector
        .OfCategory(BuiltInCategory.OST_GenericAnnotation)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elevElem in elevators)
    {
        FamilyInstance elev = elevElem as FamilyInstance;
        if (elev == null) continue;

        LocationPoint elevLoc = elev.Location as LocationPoint;
        if (elevLoc == null) continue;

        // Check for sign within 10 feet of elevator
        bool hasSign = false;
        foreach (Element signElem in signs)
        {
            FamilyInstance sign = signElem as FamilyInstance;
            if (sign == null) continue;
            string famName = sign.Symbol.FamilyName.ToLower();
            if (!famName.Contains("evacuation") && !famName.Contains("elevator sign")) continue;

            LocationPoint signLoc = sign.Location as LocationPoint;
            if (signLoc == null) continue;
            double dist = elevLoc.Point.DistanceTo(signLoc.Point);
            if (dist <= 10.0) { hasSign = true; break; }
        }

        results.Add($"Elevator {elev.Id} ({elev.Symbol.FamilyName}): Evacuation sign {(hasSign ? "FOUND" : "MISSING")} - {(hasSign ? "PASS" : "FAIL")}");
    }

    return results;
}

