public static List<string> CheckWallStudSpacing(Document doc)
{
    List<string> results = new List<string>();
    double maxSpacingFeet = 16.0 / 12.0;

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> walls = collector
        .OfCategory(BuiltInCategory.OST_Walls)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in walls)
    {
        Wall wall = elem as Wall;
        if (wall == null) continue;

        WallType wallType = wall.WallType;
        if (wallType.Kind != WallKind.Basic) continue;

        // Check structure for stud layers
        CompoundStructure cs = wallType.GetCompoundStructure();
        if (cs == null) continue;

        bool hasStudLayer = false;
        foreach (CompoundStructureLayer layer in cs.GetLayers())
        {
            if (layer.Function == MaterialFunctionAssignment.Structure)
            {
                Material mat = doc.GetElement(layer.MaterialId) as Material;
                if (mat != null && (mat.Name.ToLower().Contains("wood") || mat.Name.ToLower().Contains("stud")))
                    hasStudLayer = true;
            }
        }

        if (!hasStudLayer) continue;

        // Check spacing parameter
        Parameter spacingParam = wallType.LookupParameter("Stud Spacing");
        if (spacingParam == null) spacingParam = wallType.LookupParameter("Member Spacing");

        if (spacingParam != null)
        {
            double spacing = spacingParam.AsDouble();
            bool compliant = spacing <= maxSpacingFeet;
            results.Add($"Wall Type '{wallType.Name}': Stud spacing={spacing * 12:F0}in (max 16in) - {(compliant ? "PASS" : "FAIL")}");
        }
        else
        {
            results.Add($"Wall Type '{wallType.Name}': No stud spacing parameter - NEEDS REVIEW");
        }
    }

    return results;
}

