constraint seismic_base_shear:
    where:
        element.type == "building"
        element.seismic_analysis_method == "equivalent_lateral_force"
    require:
        # V = Cs * W
        let Sds = element.design_spectral_acceleration_short
        let Sd1 = element.design_spectral_acceleration_1s
        let R = structural.response_modification_factor(element.seismic_force_resisting_system)
        let Ie = structural.importance_factor_seismic(element.risk_category)
        let T = structural.fundamental_period(element.height, element.structure_type)
        # Seismic response coefficient
        let Cs = min(Sds / (R / Ie), Sd1 / (T * (R / Ie)))
        let Cs_min = max(0.044 * Sds * Ie, 0.01)
        let Cs_design = max(Cs, Cs_min)
        let V = Cs_design * element.effective_seismic_weight
        element.base_shear_capacity >= V
    safety_factor: 1.0
    reference: "ASCE.7.Section_12.8"

