            Parameter widthParam = door.get_Parameter(BuiltInParameter.DOOR_WIDTH);
            if (widthParam == null) continue;

            double actualWidth = widthParam.AsDouble();
            bool compliant = actualWidth >= minWidthFeet;

            results.Add($"Door {door.Id}: Width={UnitUtils.ConvertFromInternalUnits(actualWidth, UnitTypeId.Millimeters):F0}mm - {(compliant ? "PASS" : "FAIL")}");
        }

        TaskDialog.Show("BCL Door Width Check", string.Join("\n", results));
        return Result.Succeeded;
    }
}

