function tenability_time(temperature, co_concentration, visibility):
    """Time before conditions become untenable"""
    temp_limit = (120 - temperature) * 60 / 100  # seconds
    co_limit = 35000 / co_concentration  # seconds  
    vis_limit = if visibility < 5 then 0 else infinity
    return min(temp_limit, co_limit, vis_limit)

