public static List<string> CheckPipeInsulation(Document doc)
{
    double maxDia = 1.5 / 12.0;
    double minInsul = 1.0 / 12.0;
    var pipes = new FilteredElementCollector(doc)
        .OfCategory(BuiltInCategory.OST_PipeCurves)
        .WhereElementIsNotElementType().ToElements();

    var results = new List<string>();
    foreach (var elem in pipes)
    {
        var pipe = elem as Pipe;
        if (pipe == null) continue;
        var sys = pipe.get_Parameter(BuiltInParameter.RBS_PIPING_SYSTEM_TYPE_PARAM);
        if (sys == null || !sys.AsValueString().ToLower().Contains("hot")) continue;
        if (pipe.Diameter > maxDia) continue;
        var insul = pipe.get_Parameter(BuiltInParameter.RBS_REFERENCE_INSULATION_THICKNESS);
        double t = insul != null ? insul.AsDouble() : 0;
        bool ok = t >= minInsul;
        results.Add($"Pipe {pipe.Id}: {(ok ? "PASS" : "FAIL")}");
    }
    return results;
}

