            to_occ = get_room_occ(to_room)
            max_occ = max(from_occ, to_occ)

            # Check 1: Panic hardware for > 50 occupants
            if max_occ > 50:
                panic_param = door.LookupParameter('Panic Hardware')
                if panic_param and panic_param.AsInteger() == 1:
                    pass
                else:
                    issues.append('PANIC HARDWARE required (>{0} occ, IBC 1010.1.10)'.format(max_occ))

            # Check 2: Door swing direction for > 49 occupants
            if max_occ > 49:
                hand_param = door_type.LookupParameter('Door Swing')
                if hand_param:
                    swing = hand_param.AsString() or ''
                    if 'out' not in swing.lower():
                        issues.append('SWING DIRECTION: Must swing in direction of egress (IBC 1010.1.2.1)')

            # Check 3: Fire-rated door matches wall
            host_wall = door.Host
            if host_wall and isinstance(host_wall, Wall):
                wall_type = doc.GetElement(host_wall.GetTypeId())
                wall_fr_param = wall_type.LookupParameter('Fire Rating')
                if wall_fr_param is None:
                    wall_fr_param = wall_type.get_Parameter(BuiltInParameter.FIRE_RATING)
                wall_rating = parse_rating(wall_fr_param.AsString() if wall_fr_param else '')
                door_fr_param = door_type.LookupParameter('Fire Rating')
                door_rating = parse_rating(door_fr_param.AsString() if door_fr_param else '')

                if wall_rating > 0:
                    required_door_rating = 0
                    for wr, dr in sorted(DOOR_WALL_RATINGS.items(), reverse=True):
                        if wall_rating >= wr:
                            required_door_rating = dr
                            break
                    if not required_door_rating:
                        required_door_rating = wall_rating * 0.75

                    if door_rating >= required_door_rating:
                        pass
                    else:
                        issues.append('FIRE RATING: Door {0}hr in {1}hr wall, need {2}hr (IBC 716.5)'.format(
                            door_rating, wall_rating, required_door_rating))

                    # Check 4: Closer on fire-rated door
                    closer_param = door.LookupParameter('Door Closer')
                    if not (closer_param and closer_param.AsInteger() == 1):
                        issues.append('CLOSER REQUIRED on fire-rated door (IBC 716.5.9)')

                    # Check 5: Smoke gasket on smoke barrier
                    smoke_param = host_wall.LookupParameter('Smoke Barrier')
                    if smoke_param and smoke_param.AsInteger() == 1:
                        gasket_param = door.LookupParameter('Smoke Gasket')
                        if not (gasket_param and gasket_param.AsInteger() == 1):
                            issues.append('SMOKE GASKET required on smoke barrier door (IBC 716.5.3.1)')

            if issues:
                active_view.SetElementOverrides(door.Id, fail_settings)
                fail_count += 1
                results.append('FAIL: Door {0} ({1})'.format(door.Id, door_name))
                for issue in issues:
                    results.append('  * {0}'.format(issue))
                    errors.append('Door {0}: {1}'.format(door.Id, issue))
            else:
                active_view.SetElementOverrides(door.Id, pass_settings)
                pass_count += 1

        except Exception as e:
            results.append('Door {0}: Error - {1}'.format(door.Id, str(e)))

except Exception as e:
    errors.append('Critical error: {0}'.format(str(e)))

TransactionManager.Instance.TransactionTaskDone()

summary = '\n'.join(results)
summary += '\n\n=== SUMMARY ===\nPass: {0} | Fail: {1}'.format(pass_count, fail_count)
if errors:
    summary += '\n\nALL DEFICIENCIES:\n' + '\n'.join(['  * ' + e for e in errors])
OUT = summary

