public static void TagNonCompliantElements(Document doc, List<ElementId> failedIds, string ruleName)
{
    // Get or create shared parameter for compliance tagging
    using (Transaction trans = new Transaction(doc, "Tag Non-Compliant Elements"))
    {
        trans.Start();

        foreach (ElementId id in failedIds)
        {
            Element elem = doc.GetElement(id);
            if (elem == null) continue;

            // Set compliance status parameter
            Parameter compParam = elem.LookupParameter("BCL_Compliance_Status");
            if (compParam != null && !compParam.IsReadOnly)
            {
                compParam.Set("NON-COMPLIANT");
            }

            // Set compliance notes parameter
            Parameter notesParam = elem.LookupParameter("BCL_Compliance_Notes");
            if (notesParam != null && !notesParam.IsReadOnly)
            {
                notesParam.Set($"Failed rule: {ruleName}");
            }

            // Apply override graphics (red color) for visual feedback
            OverrideGraphicSettings ogs = new OverrideGraphicSettings();
            ogs.SetProjectionLineColor(new Color(255, 0, 0));
            ogs.SetSurfaceForegroundPatternColor(new Color(255, 200, 200));

            // Find a fill pattern for surface override
            FilteredElementCollector patternCollector = new FilteredElementCollector(doc);
            FillPatternElement solidPattern = patternCollector
                .OfClass(typeof(FillPatternElement))
                .Cast<FillPatternElement>()
                .FirstOrDefault(p => p.GetFillPattern().IsSolidFill);
            if (solidPattern != null)
                ogs.SetSurfaceForegroundPatternId(solidPattern.Id);

            doc.ActiveView.SetElementOverrides(id, ogs);
        }

        trans.Commit();
    }
}

