public static List<string> CheckStairHeadroom(Document doc)
{
    List<string> results = new List<string>();
    double minHeadroomFeet = UnitUtils.ConvertToInternalUnits(2000, UnitTypeId.Millimeters);

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> stairs = collector
        .OfCategory(BuiltInCategory.OST_Stairs)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in stairs)
    {
        Stairs stair = elem as Stairs;
        if (stair == null) continue;

        // Get stair bounding box for geometry analysis
        BoundingBoxXYZ bb = stair.get_BoundingBox(null);
        if (bb == null) continue;

        // Check headroom at each tread using geometry intersection
        double baseElevation = stair.get_Parameter(BuiltInParameter.STAIRS_BASE_LEVEL_PARAM) != null
            ? stair.BaseOffset
            : bb.Min.Z;

        // Approximate headroom from bounding box height minus stair height
        double stairTopZ = bb.Max.Z;

        // Use a ReferenceIntersector to check overhead clearance
        // For each riser, cast a ray upward to find the closest ceiling/floor
        Parameter headroomParam = stair.LookupParameter("Actual Headroom");
        if (headroomParam != null)
        {
            double headroom = headroomParam.AsDouble();
            bool compliant = headroom >= minHeadroomFeet;
            double headroomMm = UnitUtils.ConvertFromInternalUnits(headroom, UnitTypeId.Millimeters);
            results.Add($"Stair {stair.Id}: Headroom={headroomMm:F0}mm - {(compliant ? "PASS" : "FAIL")}");
        }
        else
        {
            results.Add($"Stair {stair.Id}: Headroom parameter not found - NEEDS MANUAL CHECK");
        }
    }

    return results;
}

