public static List<string> CheckTravelDistance(Document doc)
{
    List<string> results = new List<string>();
    double maxDistFeet = 300.0; // Sprinklered Business occupancy

    // Find exit doors
    var doors = new FilteredElementCollector(doc)
        .OfCategory(BuiltInCategory.OST_Doors)
        .WhereElementIsNotElementType()
        .ToElements();

    List<XYZ> exitPoints = new List<XYZ>();
    foreach (Element elem in doors)
    {
        FamilyInstance door = elem as FamilyInstance;
        if (door == null) continue;
        Parameter exitParam = door.LookupParameter("Is Exit");
        if (exitParam != null && exitParam.AsInteger() == 1)
        {
            LocationPoint loc = door.Location as LocationPoint;
            if (loc != null) exitPoints.Add(loc.Point);
        }
    }

    if (exitPoints.Count == 0)
    {
        results.Add("WARNING: No exit doors found in model");
        return results;
    }

    // Check each room's furthest point to nearest exit
    var rooms = new FilteredElementCollector(doc)
        .OfCategory(BuiltInCategory.OST_Rooms)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in rooms)
    {
        Room room = elem as Room;
        if (room == null || room.Area == 0) continue;

        // Get room boundary points
        SpatialElementBoundaryOptions opts = new SpatialElementBoundaryOptions();
        var boundaries = room.GetBoundarySegments(opts);
        if (boundaries == null) continue;

        double maxTravelDist = 0;
        foreach (var loop in boundaries)
        {
            foreach (var seg in loop)
            {
                // Check endpoints and midpoint of each boundary segment
                Curve curve = seg.GetCurve();
                XYZ[] testPoints = new XYZ[]
                {
                    curve.GetEndPoint(0),
                    curve.Evaluate(0.5, true),
                    curve.GetEndPoint(1)
                };

                foreach (XYZ pt in testPoints)
                {
                    double minDistToExit = double.MaxValue;
                    foreach (XYZ exitPt in exitPoints)
                    {
                        double dist = new XYZ(pt.X - exitPt.X, pt.Y - exitPt.Y, 0).GetLength();
                        minDistToExit = Math.Min(minDistToExit, dist);
                    }
                    maxTravelDist = Math.Max(maxTravelDist, minDistToExit);
                }
            }
        }

        bool compliant = maxTravelDist <= maxDistFeet;
        results.Add($"Room '{room.Name}' ({room.Id}): Max travel={maxTravelDist:F0}ft - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

public static List<string> CheckFixtureCount(Document doc)
{
    List<string> results = new List<string>();

    // Count water closets in the model
    FilteredElementCollector fixtureCollector = new FilteredElementCollector(doc);
    IList<Element> fixtures = fixtureCollector
        .OfCategory(BuiltInCategory.OST_PlumbingFixtures)
        .WhereElementIsNotElementType()
        .ToElements();

    int wcCount = 0;
    foreach (Element fixture in fixtures)
    {
        FamilyInstance fi = fixture as FamilyInstance;
        if (fi == null) continue;
        string famName = fi.Symbol.FamilyName.ToLower();
        if (famName.Contains("water closet") || famName.Contains("toilet") || famName.Contains("wc"))
            wcCount++;
    }

    // Get occupancy from project info or rooms
    FilteredElementCollector roomCollector = new FilteredElementCollector(doc);
    IList<Element> rooms = roomCollector
        .OfCategory(BuiltInCategory.OST_Rooms)
        .WhereElementIsNotElementType()
        .ToElements();

    int totalOccupants = 0;
    foreach (Element elem in rooms)
    {
        Room room = elem as Room;
        if (room == null) continue;
        Parameter occParam = room.get_Parameter(BuiltInParameter.ROOM_OCCUPANCY);
        if (occParam != null)
        {
            string occStr = occParam.AsString();
            if (int.TryParse(occStr, out int occ))
                totalOccupants += occ;
        }
    }

    // IPC Table 403.1 for Assembly: 1 WC per 125 males, 1 per 65 females
    int maleOcc = totalOccupants / 2;
    int femaleOcc = totalOccupants - maleOcc;
    int reqMaleWc = (int)Math.Ceiling(maleOcc / 125.0);
    int reqFemaleWc = (int)Math.Ceiling(femaleOcc / 65.0);
    int totalRequired = reqMaleWc + reqFemaleWc;

    bool compliant = wcCount >= totalRequired;
    results.Add($"Water Closets: Found={wcCount}, Required={totalRequired} (Male:{reqMaleWc}, Female:{reqFemaleWc}) - {(compliant ? "PASS" : "FAIL")}");

    return results;
}

public static List<string> CheckEgressDoorHardware(Document doc)
{
    List<string> results = new List<string>();

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> doors = collector
        .OfCategory(BuiltInCategory.OST_Doors)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in doors)
    {
        FamilyInstance door = elem as FamilyInstance;
        if (door == null) continue;

        // Check if door is marked as egress
        Parameter egressParam = door.LookupParameter("Is Egress");
        if (egressParam == null || !egressParam.AsInteger().Equals(1)) continue;

        // Check panic hardware
        Parameter panicParam = door.LookupParameter("Panic Hardware");
        bool hasPanic = panicParam != null && panicParam.AsInteger() == 1;

        // Check swing direction - HandFlipped and FacingFlipped
        bool handFlipped = door.HandFlipped;
        bool facingFlipped = door.FacingFlipped;
        // Determine if door swings in egress direction
        // Convention: door should swing outward (in direction of egress travel)
        Parameter swingParam = door.LookupParameter("Swing Direction");
        string swingDir = swingParam != null ? swingParam.AsString() : "unknown";

        List<string> failures = new List<string>();
        if (!hasPanic) failures.Add("Missing panic hardware");
        if (swingDir.ToLower() != "out" && swingDir.ToLower() != "egress")
            failures.Add($"Swing direction: {swingDir}");

        bool compliant = failures.Count == 0;
        string detail = compliant ? "PASS" : $"FAIL ({string.Join("; ", failures)})";
        results.Add($"Door {door.Id} ({door.Symbol.FamilyName}): {detail}");
    }

    return results;
}

