public static List<string> CheckExitSignPlacement(Document doc)
{
    List<string> results = new List<string>();
    double maxVisibilityDistFeet = 100.0; // Typical code requirement

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> genericModels = collector
        .OfCategory(BuiltInCategory.OST_LightingFixtures)
        .WhereElementIsNotElementType()
        .ToElements();

    List<FamilyInstance> exitSigns = new List<FamilyInstance>();
    foreach (Element elem in genericModels)
    {
        FamilyInstance fi = elem as FamilyInstance;
        if (fi == null) continue;
        string famName = fi.Symbol.FamilyName.ToLower();
        if (famName.Contains("exit") && famName.Contains("sign"))
            exitSigns.Add(fi);
    }

    // Collect doors marked as egress
    FilteredElementCollector doorCollector = new FilteredElementCollector(doc);
    IList<Element> doors = doorCollector
        .OfCategory(BuiltInCategory.OST_Doors)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element doorElem in doors)
    {
        FamilyInstance door = doorElem as FamilyInstance;
        if (door == null) continue;
        Parameter egressParam = door.LookupParameter("Is Egress");
        if (egressParam == null || egressParam.AsInteger() != 1) continue;

        LocationPoint doorLoc = door.Location as LocationPoint;
        if (doorLoc == null) continue;

        // Find nearest exit sign
        double minDist = double.MaxValue;
        foreach (FamilyInstance sign in exitSigns)
        {
            LocationPoint signLoc = sign.Location as LocationPoint;
            if (signLoc == null) continue;
            double dist = doorLoc.Point.DistanceTo(signLoc.Point);
            minDist = Math.Min(minDist, dist);
        }

        bool hasSign = minDist <= maxVisibilityDistFeet;
        results.Add($"Egress Door {door.Id}: Nearest exit sign={minDist:F1}ft - {(hasSign ? "PASS" : "FAIL")}");
    }

    return results;
}

public static List<string> CheckSprinklerSpacing(Document doc)
{
    List<string> results = new List<string>();
    double maxSpacingFeet = 15.0;

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> sprinklers = collector
        .OfCategory(BuiltInCategory.OST_Sprinklers)
        .WhereElementIsNotElementType()
        .ToElements();

    List<XYZ> sprinklerPoints = new List<XYZ>();
    List<ElementId> sprinklerIds = new List<ElementId>();

    foreach (Element elem in sprinklers)
    {
        FamilyInstance fi = elem as FamilyInstance;
        if (fi == null) continue;
        LocationPoint loc = fi.Location as LocationPoint;
        if (loc == null) continue;
        sprinklerPoints.Add(loc.Point);
        sprinklerIds.Add(fi.Id);
    }

    // Check nearest-neighbor distance for each sprinkler
    for (int i = 0; i < sprinklerPoints.Count; i++)
    {
        double minDist = double.MaxValue;
        for (int j = 0; j < sprinklerPoints.Count; j++)
        {
            if (i == j) continue;
            // Check only horizontal distance (same elevation)
            if (Math.Abs(sprinklerPoints[i].Z - sprinklerPoints[j].Z) > 1.0) continue;
            double dist = new XYZ(
                sprinklerPoints[i].X - sprinklerPoints[j].X,
                sprinklerPoints[i].Y - sprinklerPoints[j].Y, 0).GetLength();
            minDist = Math.Min(minDist, dist);
        }

        if (minDist < double.MaxValue)
        {
            bool compliant = minDist <= maxSpacingFeet;
            results.Add($"Sprinkler {sprinklerIds[i]}: Nearest neighbor={minDist:F1}ft (max {maxSpacingFeet}ft) - {(compliant ? "PASS" : "FAIL")}");
        }
    }

    return results;
}

