    IList<Element> floors = collector
        .OfCategory(BuiltInCategory.OST_Floors)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in floors)
    {
        Floor floor = elem as Floor;
        if (floor == null) continue;

        FloorType floorType = floor.FloorType;
        Parameter fireParam = floorType.LookupParameter("Fire Rating");
        if (fireParam == null)
            fireParam = floorType.get_Parameter(BuiltInParameter.FIRE_RATING);

        if (fireParam != null)
        {
            string ratingStr = fireParam.AsString();
            int rating = 0;
            if (!string.IsNullOrEmpty(ratingStr))
            {
                string cleaned = System.Text.RegularExpressions.Regex.Replace(ratingStr, @"[^0-9]", "");
                int.TryParse(cleaned, out rating);
                if (rating <= 4) rating *= 60;
            }

            bool compliant = rating >= requiredRating;
            results.Add($"Floor {floor.Id} (Type: {floorType.Name}): Rating={rating}min - {(compliant ? "PASS" : "FAIL")}");
        }
        else
        {
            results.Add($"Floor {floor.Id} (Type: {floorType.Name}): No fire rating - NEEDS REVIEW");
        }
    }

    return results;
}

