BCL `exists()` assertions with spatial proximity checks map to a combination of FilteredElementCollector and distance calculations in the Revit API.

**Pattern: Proximity existence check**
```csharp
public static bool ExistsNearby(
    Document doc, XYZ referencePoint, 
    BuiltInCategory targetCategory, 
    string familyNameFilter, 
    double maxDistanceFeet)
{
    var candidates = new FilteredElementCollector(doc)
        .OfCategory(targetCategory)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in candidates)
    {
        FamilyInstance fi = elem as FamilyInstance;
        if (fi == null) continue;

        // Apply name filter if specified
        if (!string.IsNullOrEmpty(familyNameFilter))
        {
            if (!fi.Symbol.FamilyName.ToLower().Contains(familyNameFilter.ToLower()))
                continue;
        }

        LocationPoint loc = fi.Location as LocationPoint;
        if (loc == null) continue;

        double distance = referencePoint.DistanceTo(loc.Point);
        if (distance <= maxDistanceFeet)
            return true;
    }

    return false;
}

// Usage for the BCL rule:
foreach (Element doorElem in egressDoors)
{
    FamilyInstance door = doorElem as FamilyInstance;
    XYZ doorPoint = (door.Location as LocationPoint).Point;

    bool hasExitSign = ExistsNearby(
        doc, doorPoint,
        BuiltInCategory.OST_LightingFixtures,
        "exit sign",
        100.0); // 100 feet

    // Report result
}
```

**For more precise proximity (BoundingBox-based pre-filter):**
```csharp
public static bool ExistsWithinBoundingBox(
    Document doc, XYZ center, double radius,
    BuiltInCategory category)
{
    // Create an outline for a spatial filter
    Outline searchArea = new Outline(
        new XYZ(center.X - radius, center.Y - radius, center.Z - 10),
        new XYZ(center.X + radius, center.Y + radius, center.Z + 10));

    BoundingBoxIntersectsFilter bbFilter = 
        new BoundingBoxIntersectsFilter(searchArea);

    var nearby = new FilteredElementCollector(doc)
        .OfCategory(category)
        .WherePasses(bbFilter)
        .WhereElementIsNotElementType()
        .ToElements();

    return nearby.Count > 0;
}
```

The BoundingBox pre-filter is much faster for large models, as it uses Revit's spatial index instead of iterating all elements.

public static List<string> CheckReceptacleSpacing(Document doc)
{
    List<string> results = new List<string>();
    double maxSpacingFeet = 12.0;
    double maxCornerDistFeet = 6.0;

    // Collect all electrical fixtures (receptacles)
    FilteredElementCollector receptacleCollector = new FilteredElementCollector(doc);
    IList<Element> receptacles = receptacleCollector
        .OfCategory(BuiltInCategory.OST_ElectricalFixtures)
        .WhereElementIsNotElementType()
        .ToElements();

    // Filter to receptacle outlets
    List<FamilyInstance> outlets = new List<FamilyInstance>();
    foreach (Element elem in receptacles)
    {
        FamilyInstance fi = elem as FamilyInstance;
        if (fi == null) continue;
        string famName = fi.Symbol.FamilyName.ToLower();
        if (famName.Contains("receptacle") || famName.Contains("outlet") || famName.Contains("duplex"))
            outlets.Add(fi);
    }

    // Collect walls
    FilteredElementCollector wallCollector = new FilteredElementCollector(doc);
    IList<Element> walls = wallCollector
        .OfCategory(BuiltInCategory.OST_Walls)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element wallElem in walls)
    {
        Wall wall = wallElem as Wall;
        if (wall == null) continue;

        LocationCurve wallLoc = wall.Location as LocationCurve;
        if (wallLoc == null) continue;
        Curve wallCurve = wallLoc.Curve;
        double wallLength = wallCurve.Length;

        // Find outlets hosted on this wall
        List<double> outletPositions = new List<double>();
        foreach (FamilyInstance outlet in outlets)
        {
            if (outlet.Host != null && outlet.Host.Id == wall.Id)
            {
                LocationPoint outletLoc = outlet.Location as LocationPoint;
                if (outletLoc != null)
                {
                    IntersectionResult ir = wallCurve.Project(outletLoc.Point);
                    if (ir != null)
                        outletPositions.Add(ir.Parameter);
                }
            }
        }

        outletPositions.Sort();

        if (wallLength < 2.0) continue; // Skip short walls

        // Check corner distance (first and last outlet)
        if (outletPositions.Count == 0)
        {
            results.Add($"Wall {wall.Id}: No outlets on {wallLength * 12:F0}in wall - FAIL");
            continue;
        }

        bool cornerOk = outletPositions[0] <= maxCornerDistFeet / wallLength;
        bool endOk = (1.0 - outletPositions[outletPositions.Count - 1]) * wallLength <= maxCornerDistFeet;

        // Check spacing between consecutive outlets
        bool spacingOk = true;
        for (int i = 1; i < outletPositions.Count; i++)
        {
            double gap = (outletPositions[i] - outletPositions[i - 1]) * wallLength;
            if (gap > maxSpacingFeet) { spacingOk = false; break; }
        }

        bool compliant = cornerOk && endOk && spacingOk;
        results.Add($"Wall {wall.Id}: {outletPositions.Count} outlets - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

