        if (railType == null) continue;

        Parameter heightParam = railType.get_Parameter(BuiltInParameter.RAILING_HEIGHT_OFFSET);
        if (heightParam == null)
            heightParam = railType.LookupParameter("Top Rail Height");
        if (heightParam == null) continue;

        double height = heightParam.AsDouble();
        bool compliant = height >= minHeightFeet;

        double heightMm = UnitUtils.ConvertFromInternalUnits(height, UnitTypeId.Millimeters);
        results.Add($"Railing {railing.Id} ({railType.Name}): Height={heightMm:F0}mm (min 1100mm) - {(compliant ? "PASS" : "FAIL")}");
