public static List<string> CheckWallFireRating(Document doc)
{
    List<string> results = new List<string>();
    int requiredRatingMinutes = 60;

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> walls = collector
        .OfCategory(BuiltInCategory.OST_Walls)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in walls)
    {
        Wall wall = elem as Wall;
        if (wall == null) continue;

        WallType wallType = wall.WallType;
        Parameter fireRatingParam = wallType.LookupParameter("Fire Rating");
        if (fireRatingParam == null)
            fireRatingParam = wallType.get_Parameter(BuiltInParameter.FIRE_RATING);
        if (fireRatingParam == null)
        {
            results.Add($"Wall {wall.Id} (Type: {wallType.Name}): No fire rating parameter - NEEDS REVIEW");
            continue;
        }

        string ratingStr = fireRatingParam.AsString();
        int ratingMinutes = 0;
        if (!string.IsNullOrEmpty(ratingStr))
        {
            // Parse common formats: "60", "1 HR", "60 MIN"
            ratingStr = ratingStr.ToUpper().Replace("HR", "").Replace("MIN", "").Trim();
            if (int.TryParse(ratingStr, out int parsed))
            {
                ratingMinutes = parsed <= 4 ? parsed * 60 : parsed; // Assume small numbers are hours
            }
        }

        bool compliant = ratingMinutes >= requiredRatingMinutes;
        results.Add($"Wall {wall.Id} (Type: {wallType.Name}): Rating={ratingMinutes}min - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

