        let qh = structural.velocity_pressure_at_height(
            element.building.roof_height,
            element.building.exposure_category
        )
        let GCp_positive = structural.external_pressure_coefficient(
            element.effective_area, "roof_equipment", "positive"
        )
        let GCp_negative = structural.external_pressure_coefficient(
            element.effective_area, "roof_equipment", "negative"
        )
        let GCpi = structural.internal_pressure_coefficient(element.building.enclosure_class)
        # Design pressure
        let p_positive = qh * (GCp_positive - GCpi)
        let p_negative = qh * (GCp_negative + GCpi)
        # Unit must resist both positive and negative pressures
        element.anchorage_capacity >= abs(p_negative) * element.projected_area
        element.dead_weight + element.anchorage_capacity >= abs(p_negative) * element.projected_area
    safety_factor: 1.5
    reference: "ASCE.7.Section_30.11"

