**BCL to Revit mapping:**
```csharp
// BCL: room.occupancy_load = room.area / occupancy_factor
public static int CalculateOccupancyLoad(Room room, Document doc)
{
    // Get room area in sqft
    double areaSqFt = room.Area;

    // Get occupancy type from room parameter
    Parameter occParam = room.get_Parameter(BuiltInParameter.ROOM_OCCUPANCY);
    string occType = occParam?.AsString()?.ToLower() ?? "office";

    // IBC Table 1004.5 occupancy load factors (sqft/person)
    Dictionary<string, double> loadFactors = new Dictionary<string, double>
    {
        { "assembly_standing", 5 },
        { "assembly_concentrated", 7 },
        { "assembly_unconcentrated", 15 },
        { "business", 150 },
        { "educational", 20 },
        { "industrial", 100 },
        { "mercantile_ground", 30 },
        { "mercantile_upper", 60 },
        { "office", 150 },
        { "residential", 200 },
        { "storage", 300 },
        { "warehouse", 500 }
    };

    double factor = 150; // default to office
    foreach (var kvp in loadFactors)
    {
        if (occType.Contains(kvp.Key))
        {
            factor = kvp.Value;
            break;
        }
    }

    return (int)Math.Ceiling(areaSqFt / factor);
}
```

**Writing results back to the model:**
```csharp
