public static List<string> CheckPanelWorkingSpace(Document doc)
{
    List<string> results = new List<string>();
    double minDepthFeet = 36.0 / 12.0; // 36 inches = 3 feet

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> panels = collector
        .OfCategory(BuiltInCategory.OST_ElectricalEquipment)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element panel in panels)
    {
        FamilyInstance fi = panel as FamilyInstance;
        if (fi == null) continue;

        // Get panel location
        LocationPoint loc = fi.Location as LocationPoint;
        if (loc == null) continue;
        XYZ panelPoint = loc.Point;
        XYZ facingDir = fi.FacingOrientation;

        // Check clearance in front of panel using ray casting
        // Project a ray from panel face in the facing direction
        ReferenceIntersector refIntersector = new ReferenceIntersector(
            new ElementClassFilter(typeof(Wall)),
            FindReferenceTarget.Face,
            (View3D)new FilteredElementCollector(doc)
                .OfClass(typeof(View3D))
                .FirstElement());

        ReferenceWithContext refContext = refIntersector.FindNearest(panelPoint, facingDir);
        double clearance = refContext != null ? refContext.Proximity : double.MaxValue;

