public static List<string> CheckDrainPipeSizing(Document doc)
{
    List<string> results = new List<string>();

    // DFU to minimum pipe diameter mapping (IPC Table 710.1)
    Dictionary<int, double> dfuToPipeSize = new Dictionary<int, double>
    {
        { 1, 1.25 }, { 3, 1.5 }, { 6, 2.0 }, { 12, 2.5 },
        { 20, 3.0 }, { 160, 4.0 }, { 360, 5.0 }, { 620, 6.0 },
        { 1400, 8.0 }, { 2500, 10.0 }, { 3900, 12.0 }
    };

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> pipes = collector
        .OfCategory(BuiltInCategory.OST_PipeCurves)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in pipes)
    {
        Pipe pipe = elem as Pipe;
        if (pipe == null) continue;

        // Check if sanitary system
        Parameter sysTypeParam = pipe.get_Parameter(BuiltInParameter.RBS_PIPING_SYSTEM_TYPE_PARAM);
        if (sysTypeParam == null) continue;
        string sysType = sysTypeParam.AsValueString();
        if (!sysType.ToLower().Contains("sanitary")) continue;

        // Get pipe diameter
        double diameter = pipe.Diameter * 12.0; // Convert feet to inches

        // Get fixture units served (custom parameter or calculated)
        Parameter dfuParam = pipe.LookupParameter("Total Fixture Units");
        if (dfuParam == null) continue;
        int totalDfu = (int)dfuParam.AsDouble();

        // Find required pipe size
        double requiredDia = 1.25;
        foreach (var kvp in dfuToPipeSize.OrderBy(x => x.Key))
        {
            if (totalDfu <= kvp.Key)
            {
                requiredDia = kvp.Value;
                break;
            }
        }

        bool compliant = diameter >= requiredDia;
        results.Add($"Pipe {pipe.Id}: Dia={diameter:F2}in, DFU={totalDfu}, Required={requiredDia}in - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

