**Parsing Fire Rating Strings:**
Revit stores fire ratings as strings in various formats. A robust parser:

```csharp
public static int ParseFireRatingMinutes(string ratingStr)
{
    if (string.IsNullOrEmpty(ratingStr)) return 0;

    ratingStr = ratingStr.ToUpper().Trim();

    // Handle common formats
    if (ratingStr.Contains("HR") || ratingStr.Contains("HOUR"))
    {
        // "1 HR", "1.5 HOUR", "2 HR"
        string numStr = Regex.Match(ratingStr, @"[\d.]+").Value;
        if (double.TryParse(numStr, out double hours))
            return (int)(hours * 60);
    }

    if (ratingStr.Contains("MIN"))
    {
        // "60 MIN", "90 MIN"
        string numStr = Regex.Match(ratingStr, @"\d+").Value;
        if (int.TryParse(numStr, out int mins))
            return mins;
    }

    // Plain number: small = hours, large = minutes
    string digits = Regex.Replace(ratingStr, @"[^\d]", "");
    if (int.TryParse(digits, out int val))
        return val <= 4 ? val * 60 : val;

    return 0;
}
```

