```csharp
public static List<string> CheckInstitutionalStairRise(Document doc)
{
    // Map BCL IN operator to a HashSet for O(1) lookup
    HashSet<string> applicableUses = new HashSet<string>(
        new[] { "institutional", "assembly" },
        StringComparer.OrdinalIgnoreCase);

    // Check building use from Project Information
    ProjectInfo projInfo = doc.ProjectInformation;
    Parameter useParam = projInfo.LookupParameter("Building Use");
    string buildingUse = useParam?.AsString()?.ToLower() ?? "";

    if (!applicableUses.Contains(buildingUse))
        return new List<string> { "Rule not applicable: building use is not institutional or assembly" };

    double maxRiseFeet = UnitUtils.ConvertToInternalUnits(190, UnitTypeId.Millimeters);

    var stairs = new FilteredElementCollector(doc)
        .OfCategory(BuiltInCategory.OST_Stairs)
        .WhereElementIsNotElementType()
        .ToElements();

    List<string> results = new List<string>();
    foreach (Element elem in stairs)
    {
        Stairs stair = elem as Stairs;
        if (stair == null) continue;

        bool compliant = stair.ActualRiserHeight <= maxRiseFeet;
        double riserMm = UnitUtils.ConvertFromInternalUnits(
            stair.ActualRiserHeight, UnitTypeId.Millimeters);
        results.Add($"Stair {stair.Id}: Rise={riserMm:F1}mm - {(compliant ? "PASS" : "FAIL")}");
    }
    return results;
}
