public static List<string> CheckCorridorWidth(Document doc)
{
    List<string> results = new List<string>();
    double minWidthFeet = 44.0 / 12.0; // 44 inches in feet (Revit internal units)

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> rooms = collector
        .OfCategory(BuiltInCategory.OST_Rooms)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in rooms)
    {
        Room room = elem as Room;
        if (room == null) continue;

        Parameter nameParam = room.get_Parameter(BuiltInParameter.ROOM_NAME);
        if (nameParam == null) continue;
        string roomName = nameParam.AsString().ToLower();
        if (!roomName.Contains("corridor") && !roomName.Contains("hallway")) continue;

        SpatialElementBoundaryOptions options = new SpatialElementBoundaryOptions();
        IList<IList<BoundarySegment>> boundaries = room.GetBoundarySegments(options);
        if (boundaries == null || boundaries.Count == 0) continue;

        // Approximate width from area and perimeter
        double area = room.Area; // sq feet
        double perimeter = 0;
        foreach (IList<BoundarySegment> loop in boundaries)
        {
            foreach (BoundarySegment seg in loop)
            {
                perimeter += seg.GetCurve().Length;
            }
        }

        // For a rectangular corridor: width = (perimeter - sqrt(perimeter^2 - 16*area)) / 4
        double discriminant = perimeter * perimeter - 16 * area;
        if (discriminant < 0) continue;
        double estimatedWidth = (perimeter - Math.Sqrt(discriminant)) / 4.0;

        bool compliant = estimatedWidth >= minWidthFeet;
        double widthInches = estimatedWidth * 12.0;
        results.Add($"Room '{nameParam.AsString()}' (Id:{room.Id}): Width~{widthInches:F1}in - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

