Implementing batch BCL compliance checking requires a structured framework that iterates through all applicable rules and collects results.

**Architecture:**
```csharp
// Define a BCL rule checker interface
public interface IBCLRuleChecker
{
    string RuleName { get; }
    string Reference { get; }
    BuiltInCategory[] ApplicableCategories { get; }
    List<ComplianceResult> Check(Document doc);
}

public class ComplianceResult
{
    public ElementId ElementId { get; set; }
    public string ElementDescription { get; set; }
    public bool Compliant { get; set; }
    public string Details { get; set; }
    public string RuleName { get; set; }
    public string Reference { get; set; }
}

// Example rule implementation
public class DoorWidthChecker : IBCLRuleChecker
{
    public string RuleName => "door_width_accessible";
    public string Reference => "UK.ADoc.M.Section_2.7";
    public BuiltInCategory[] ApplicableCategories => 
        new[] { BuiltInCategory.OST_Doors };

    public List<ComplianceResult> Check(Document doc)
    {
        var results = new List<ComplianceResult>();
        double minWidth = UnitUtils.ConvertToInternalUnits(850, UnitTypeId.Millimeters);

        var doors = new FilteredElementCollector(doc)
            .OfCategory(BuiltInCategory.OST_Doors)
            .WhereElementIsNotElementType().ToElements();

        foreach (Element elem in doors)
        {
            var wp = elem.get_Parameter(BuiltInParameter.DOOR_WIDTH);
            if (wp == null) continue;
            double w = wp.AsDouble();
            results.Add(new ComplianceResult
            {
                ElementId = elem.Id,
                ElementDescription = $"Door {elem.Id}",
                Compliant = w >= minWidth,
                Details = $"Width: {w * 304.8:F0}mm",
                RuleName = RuleName,
                Reference = Reference
            });
        }
        return results;
    }
}

// Batch runner
public class BCLBatchChecker
{
    private List<IBCLRuleChecker> _rules = new List<IBCLRuleChecker>();

    public BCLBatchChecker()
    {
        // Register all rule checkers
        _rules.Add(new DoorWidthChecker());
        _rules.Add(new StairRiserChecker());
        _rules.Add(new WallFireRatingChecker());
        _rules.Add(new RampSlopeChecker());
        _rules.Add(new CeilingHeightChecker());
        _rules.Add(new GuardRailHeightChecker());
        // ... add all rules
    }

    public BatchComplianceReport RunAll(Document doc)
    {
        var report = new BatchComplianceReport();
        report.ProjectName = doc.Title;
        report.CheckDate = DateTime.Now;

        foreach (var rule in _rules)
        {
            var ruleResults = rule.Check(doc);
            report.Results.AddRange(ruleResults);
            report.RuleSummaries.Add(new RuleSummary
            {
                RuleName = rule.RuleName,
                Reference = rule.Reference,
                TotalChecked = ruleResults.Count,
                Passed = ruleResults.Count(r => r.Compliant),
                Failed = ruleResults.Count(r => !r.Compliant)
            });
        }

        return report;
    }
}
```

**Usage as IExternalCommand:**
```csharp
public Result Execute(ExternalCommandData cmdData, ref string msg, ElementSet elements)
{
    Document doc = cmdData.Application.ActiveUIDocument.Document;
    var checker = new BCLBatchChecker();
    var report = checker.RunAll(doc);

    // Display summary
    string summary = $"BCL Compliance Report\n" +
        $"Total rules: {report.RuleSummaries.Count}\n" +
        $"Total checks: {report.Results.Count}\n" +
        $"Passed: {report.Results.Count(r => r.Compliant)}\n" +
        $"Failed: {report.Results.Count(r => !r.Compliant)}";

    TaskDialog.Show("BCL Batch Check", summary);
    return Result.Succeeded;
}
