To track BCL compliance results on individual Revit elements, you need shared parameters that can be added to element categories. This enables persistent compliance data in the model.

**Step 1: Define the shared parameter file and parameters**
```csharp
public static void CreateBCLComplianceParameters(UIApplication uiApp)
{
    Document doc = uiApp.ActiveUIDocument.Document;
    Application app = uiApp.Application;

    // Create or open shared parameter file
    string sharedParamFile = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
        "BCL_SharedParams.txt");

    if (!File.Exists(sharedParamFile))
        File.Create(sharedParamFile).Close();

    app.SharedParametersFilename = sharedParamFile;
    DefinitionFile defFile = app.OpenSharedParameterFile();

