        categories.Insert(doc.Settings.Categories.get_Item(BuiltInCategory.OST_Rooms));
        categories.Insert(doc.Settings.Categories.get_Item(BuiltInCategory.OST_Railings));
        categories.Insert(doc.Settings.Categories.get_Item(BuiltInCategory.OST_Windows));
        categories.Insert(doc.Settings.Categories.get_Item(BuiltInCategory.OST_PipeCurves));
        categories.Insert(doc.Settings.Categories.get_Item(BuiltInCategory.OST_DuctCurves));

        InstanceBinding binding = doc.Application.Create.NewInstanceBinding(categories);
        doc.ParameterBindings.Insert(paramDef, binding, BuiltInParameterGroup.PG_DATA);

        trans.Commit();
    }
}
