public static void WriteComplianceResult(
    Document doc, ElementId elementId, bool passed, string ruleName)
{
    Element elem = doc.GetElement(elementId);

    Parameter statusParam = elem.LookupParameter("BCL_Compliance_Status");
    if (statusParam != null && !statusParam.IsReadOnly)
        statusParam.Set(passed ? "PASS" : "FAIL");

    Parameter notesParam = elem.LookupParameter("BCL_Compliance_Notes");
    if (notesParam != null && !notesParam.IsReadOnly)
    {
        string existing = notesParam.AsString() ?? "";
        string newNote = $"{ruleName}: {(passed ? "PASS" : "FAIL")}";
        notesParam.Set(string.IsNullOrEmpty(existing) ? newNote : $"{existing}; {newNote}");
    }

    Parameter dateParam = elem.LookupParameter("BCL_Last_Check_Date");
    if (dateParam != null && !dateParam.IsReadOnly)
        dateParam.Set(DateTime.Now.ToString("yyyy-MM-dd HH:mm"));
}
