public static List<string> CheckBoilerClearances(Document doc)
{
    List<string> results = new List<string>();

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> equipment = collector
        .OfCategory(BuiltInCategory.OST_MechanicalEquipment)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in equipment)
    {
        FamilyInstance fi = elem as FamilyInstance;
        if (fi == null) continue;
        string famName = fi.Symbol.FamilyName.ToLower();
        if (!famName.Contains("boiler") && !famName.Contains("water heater")) continue;

        LocationPoint loc = fi.Location as LocationPoint;
        if (loc == null) continue;

        // Get required clearance from family parameter
        Parameter reqClearParam = fi.LookupParameter("Required Clearance");
        double reqClearance = reqClearParam != null ? reqClearParam.AsDouble() : 3.0 / 12.0; // Default 3 inches
        double safeReqClearance = reqClearance * 1.5; // Apply 1.5 safety factor

        // Get bounding box to check actual clearances
        BoundingBoxXYZ bb = fi.get_BoundingBox(null);
        if (bb == null) continue;

        // Find nearest wall or combustible element
        FilteredElementCollector wallCollector = new FilteredElementCollector(doc);
        IList<Element> nearbyWalls = wallCollector
            .OfCategory(BuiltInCategory.OST_Walls)
            .WhereElementIsNotElementType()
            .ToElements();

        double minClearance = double.MaxValue;
        foreach (Element wallElem in nearbyWalls)
        {
            BoundingBoxXYZ wallBb = wallElem.get_BoundingBox(null);
            if (wallBb == null) continue;
            double dist = Math.Max(0,
                Math.Max(bb.Min.X - wallBb.Max.X, wallBb.Min.X - bb.Max.X) +
                Math.Max(bb.Min.Y - wallBb.Max.Y, wallBb.Min.Y - bb.Max.Y));
            minClearance = Math.Min(minClearance, dist);
        }

        bool compliant = minClearance >= safeReqClearance;
        results.Add($"Boiler {fi.Id}: Clearance={minClearance * 12:F1}in, Required={safeReqClearance * 12:F1}in (incl. 1.5x SF) - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

