public static List<string> CheckConcreteCovers(Document doc)
{
    List<string> results = new List<string>();
    double minCoverFeet = UnitUtils.ConvertToInternalUnits(25, UnitTypeId.Millimeters);

    // Check structural columns
    FilteredElementCollector colCollector = new FilteredElementCollector(doc);
    IList<Element> columns = colCollector
        .OfCategory(BuiltInCategory.OST_StructuralColumns)
        .WhereElementIsNotElementType()
        .ToElements();

    // Check beams
    FilteredElementCollector beamCollector = new FilteredElementCollector(doc);
    IList<Element> beams = beamCollector
        .OfCategory(BuiltInCategory.OST_StructuralFraming)
        .WhereElementIsNotElementType()
        .ToElements();

    List<Element> allElements = new List<Element>();
    allElements.AddRange(columns);
    allElements.AddRange(beams);

    foreach (Element elem in allElements)
    {
        // Check rebar cover parameters
        Parameter coverTopParam = elem.LookupParameter("Rebar Cover - Top Face");
        Parameter coverBotParam = elem.LookupParameter("Rebar Cover - Bottom Face");
        Parameter coverOtherParam = elem.LookupParameter("Rebar Cover - Other Faces");

        List<string> failures = new List<string>();
