public static List<string> CheckAccessibleToiletClearance(Document doc)
{
    List<string> results = new List<string>();
    double minClearSpaceFeet = 60.0 / 12.0; // 60 inches = 5 feet
    double minDoorWidthFeet = 32.0 / 12.0;

    var rooms = new FilteredElementCollector(doc)
        .OfCategory(BuiltInCategory.OST_Rooms)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in rooms)
    {
        Room room = elem as Room;
        if (room == null || room.Area == 0) continue;

        string name = room.Name.ToLower();
        if (!name.Contains("toilet") && !name.Contains("restroom") && !name.Contains("bathroom"))
            continue;

        // Check if accessible
        Parameter accessParam = room.LookupParameter("Is Accessible");
        if (accessParam != null && accessParam.AsInteger() != 1) continue;

        List<string> failures = new List<string>();

        // Check room dimensions from bounding box
        BoundingBoxXYZ bb = room.get_BoundingBox(null);
        if (bb != null)
        {
            double width = bb.Max.X - bb.Min.X;
            double depth = bb.Max.Y - bb.Min.Y;
            double minDim = Math.Min(width, depth);

            if (minDim < minClearSpaceFeet)
                failures.Add($"Min dim: {minDim * 12:F0}in (need 60in)");
        }

        // Check door widths into this room
        var doors = new FilteredElementCollector(doc)
            .OfCategory(BuiltInCategory.OST_Doors)
            .WhereElementIsNotElementType()
            .ToElements();

        foreach (Element doorElem in doors)
        {
            FamilyInstance door = doorElem as FamilyInstance;
            if (door == null) continue;

            // Check if door serves this room
            if ((door.FromRoom?.Id == room.Id) || (door.ToRoom?.Id == room.Id))
            {
                Parameter doorWidth = door.get_Parameter(BuiltInParameter.DOOR_WIDTH);
                if (doorWidth != null)
                {
                    double dw = doorWidth.AsDouble();
                    if (dw < minDoorWidthFeet)
                        failures.Add($"Door {door.Id}: {dw * 12:F0}in (need 32in)");
                }
            }
        }

        bool compliant = failures.Count == 0;
        string detail = compliant ? "All clearances OK" : string.Join("; ", failures);
        results.Add($"Room '{room.Name}' ({room.Id}): {detail} - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

public static List<string> CheckPipeInsulation(Document doc)
{
    List<string> results = new List<string>();
    double maxPipeDiaFeet = 1.5 / 12.0;
    double minInsulFeet = 1.0 / 12.0;

    FilteredElementCollector collector = new FilteredElementCollector(doc);
    IList<Element> pipes = collector
        .OfCategory(BuiltInCategory.OST_PipeCurves)
        .WhereElementIsNotElementType()
        .ToElements();

    foreach (Element elem in pipes)
    {
        Pipe pipe = elem as Pipe;
        if (pipe == null) continue;

        // Check system type
        Parameter sysParam = pipe.get_Parameter(BuiltInParameter.RBS_PIPING_SYSTEM_TYPE_PARAM);
        if (sysParam == null) continue;
        string sysType = sysParam.AsValueString();
        if (!sysType.ToLower().Contains("hot") && !sysType.ToLower().Contains("domestic hot")) continue;

        double diameter = pipe.Diameter;
        if (diameter > maxPipeDiaFeet) continue; // Only check pipes <= 1.5"

        // Check insulation
        Parameter insulParam = pipe.get_Parameter(BuiltInParameter.RBS_REFERENCE_INSULATION_THICKNESS);
        double insulThickness = insulParam != null ? insulParam.AsDouble() : 0;

        bool compliant = insulThickness >= minInsulFeet;
        results.Add($"Pipe {pipe.Id}: Dia={diameter * 12:F2}in, Insulation={insulThickness * 12:F2}in (min 1.0in) - {(compliant ? "PASS" : "FAIL")}");
    }

    return results;
}

Fire rating parameters in Revit are typically stored as string values (e.g., "1 HR", "60 MIN", "2", "Non-Rated"), while BCL rules compare against numeric values in minutes. A robust parser is needed.

**The Problem:**
```
// BCL rule:
element.fire_resistance >= 60.minutes

// Revit stores fire rating as a string:
// "60" or "1 HR" or "60 MIN" or "1.0" or "Non-Rated" or ""
```

**Complete parsing solution in C#:**
```csharp
public static int ParseFireRatingToMinutes(Parameter fireParam)
{
    if (fireParam == null) return 0;

    // Handle both string and numeric parameter types
    string rawValue;
    if (fireParam.StorageType == StorageType.String)
        rawValue = fireParam.AsString();
    else if (fireParam.StorageType == StorageType.Double)
        return (int)(fireParam.AsDouble() * 60); // Assume hours
    else if (fireParam.StorageType == StorageType.Integer)
        return fireParam.AsInteger() <= 4 ? fireParam.AsInteger() * 60 : fireParam.AsInteger();
    else
        return 0;

    if (string.IsNullOrWhiteSpace(rawValue)) return 0;
    rawValue = rawValue.Trim().ToUpper();

    // Non-rated checks
    if (rawValue == "NR" || rawValue == "NON-RATED" || rawValue == "NONE" || rawValue == "0")
        return 0;

    // "1 HR", "2 HOUR", "1.5 HR"
    var hourMatch = Regex.Match(rawValue, @"([\d.]+)\s*(HR|HOUR|HRS|HOURS)");
    if (hourMatch.Success)
    {
        if (double.TryParse(hourMatch.Groups[1].Value, out double hrs))
            return (int)(hrs * 60);
    }

    // "60 MIN", "90 MINUTES"
    var minMatch = Regex.Match(rawValue, @"(\d+)\s*(MIN|MINUTES)");
    if (minMatch.Success)
    {
        if (int.TryParse(minMatch.Groups[1].Value, out int mins))
            return mins;
    }

    // Plain number: "60", "90", "120" or "1", "2"
    var numMatch = Regex.Match(rawValue, @"^(\d+)$");
    if (numMatch.Success)
    {
        int val = int.Parse(numMatch.Groups[1].Value);
        // Numbers 1-4 are likely hours; 20+ are minutes
        return val <= 4 ? val * 60 : val;
    }

    return 0;
}
```

**Usage:**
```csharp
Parameter fp = wallType.get_Parameter(BuiltInParameter.FIRE_RATING);
if (fp == null) fp = wallType.LookupParameter("Fire Rating");
int ratingMinutes = ParseFireRatingToMinutes(fp);

// BCL comparison
bool compliant = ratingMinutes >= 60; // element.fire_resistance >= 60.minutes
```

**Dynamo Python version:**
```python
def parse_fire_rating(param):
    if param is None:
        return 0
    val = param.AsString()
    if not val:
        return 0
    val = val.upper().strip()
    if val in ['NR', 'NON-RATED', 'NONE', '0']:
        return 0
    import re
    hr = re.search(r'([\d.]+)\s*(HR|HOUR)', val)
    if hr:
        return int(float(hr.group(1)) * 60)
    mn = re.search(r'(\d+)\s*MIN', val)
    if mn:
        return int(mn.group(1))
    digits = re.sub(r'[^\d]', '', val)
    if digits:
        n = int(digits)
        return n * 60 if n <= 4 else n
    return 0
```

